import Vue from 'vue';
import { Component, Prop } from 'vue-property-decorator';
import { IRequirements } from '../../../../types';
import { IRequirementsState } from '../../types';
import NicknameRequirement from './requirement/index.vue';

@Component({
    components: {
        NicknameRequirement
    }
})
export default class NicknameRequirements extends Vue {
    @Prop()
    protected translations: IRequirements;

    @Prop()
    protected state: IRequirementsState;

    get allRequirementsMet(): boolean {
        return this.state.alphaNumeric && this.state.length && this.state.startingCharacter;
    }
}
